export function resolveStagingSupplyForecastProfile(
  timestampMs = Date.now(),
): SupplyForecastProfile {
  const profile = (STAGING_SUPPLY_FORECAST.profiles as readonly SupplyForecastProfile[]).find((entry) => {
    const from = Date.parse(entry.effectiveFrom);
    const until = entry.effectiveUntil === null ? Number.POSITIVE_INFINITY : Date.parse(entry.effectiveUntil);
    return timestampMs >= from && timestampMs < until;
  }) ?? null;
  if (!profile) throw new Error("The staging supply forecast has no profile for the requested time.");
  return profile;
}
